private TreeNode<T> rotateRight(TreeNode<T> node) {
	if (node == null) {
		throw new IllegalArgumentException("Cannot rotate null node");
	}
	TreeNode<T> parent = node.parent;
	if (parent == null) {
		throw new IllegalArgumentException("Cannot rotate root node");
	}
	TreeNode<T> grandparent = parent.parent;
	if (grandparent == null) {
		throw new IllegalArgumentException("Cannot rotate sub-root node");
	}
	if (grandparent.left != parent) {
		throw new IllegalArgumentException("Cannot rotate node with improper parent");
	}
	TreeNode<T> sibling = parent.right;
	if (sibling == null) {
		throw new IllegalArgumentException("Cannot rotate leaf node");
	}
	TreeNode<T> siblingLeft = sibling.left;
	TreeNode<T> siblingRight = sibling.right;
	node.parent = sibling;
	sibling.left = node;
	if (siblingLeft != null) {
		siblingLeft.parent = node;
	}
	if (siblingRight != null) {
		siblingRight.parent = node;
	}
	parent.right = siblingLeft;
	if (parent.left != null) {
		parent.left.parent = parent;
	}
	grandparent.left = sibling;
	if (siblingLeft != null) {
		siblingLeft.parent = grandparent;
	}
	if (siblingRight != null) {
		siblingRight.parent = grandparent;
	}
	return sibling;
}

