public List<TimeRange> buildTimeRanges(long start, long end){
    // Validation
    if (start < 0 || end < 0 || end < start) {
        throw new IllegalArgumentException("Invalid input: start=" + start + ", end=" + end);
    }

    if (end - start > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Duration is too long: " + (end - start) + "ms");
    }

    // Build time ranges
    List<TimeRange> timeRanges = new ArrayList<>();
    if (end - start > 0) {
        long timeSinceMidnight = start % (24 * 60 * 60 * 1000L);
        long endMillis = end - timeSinceMidnight;
        long startMillis = start;
        while (startMillis < endMillis) {
            long splitStart = startMillis;
            long splitEnd = Math.min(endMillis, startMillis + FETCH_DATA_DURATION);
            timeRanges.add(new TimeRange(splitStart, splitEnd));
            startMillis = splitEnd;
        }
    }

    return timeRanges;
    }

public List<TimeRange> buildTimeRanges(long start, long end) {
  List<TimeRange> timeRanges = new ArrayList<>();

  if (start + end <= FETCH_DATA_DURATION) {
    timeRanges.add(new TimeRange(start, end));
  } else {
    long middle = start + (end - start) / 2;
    timeRanges.addAll(buildTimeRanges(start, middle));
    timeRanges.addAll(buildTimeRanges(middle, end));
  }

  return timeRanges;
}

