public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 100000000000000L || timeBucket > 99999999999999L) {
      throw new IllegalArgumentException("Invalid time bucket value");
    }

    int day = (int) (timeBucket / 1000000);
    int compressDay = (int) (day / dayStep) * dayStep;
    long compressTimeBucket = (long) compressDay * 1000000 + timeBucket % 1000000;

    return compressTimeBucket;
  }

