    int month = cal.get(Calendar.MONTH) + 1;
    int day = cal.get(Calendar.DATE);
    day = day - day%dayStep;
    if (day < 10) {
      String dayStr = "0" + day;
      timeBucket = Long.parseLong(year+""+month+""+dayStr);
    } else {
      timeBucket = Long.parseLong(year+""+month+""+day);
