  if (timeBucket < 0) {
    throw new IllegalArgumentException("timeBucket must be a valid date");
  }

  // Compress the timeBucket by substracting the last two digits and multiplying by dayStep
  long result = (timeBucket / 100) * dayStep + (timeBucket % 100) / dayStep;

  // Check if the result is a valid date
  if (result < 0) {
