public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) { 
    // Create a new LinkedBuffer that will contain the UTF-8 escaped characters 
    LinkedBuffer escaped = new LinkedBuffer(lb.size() * 2); 
    for (int i = 0; i < str.length(); i++) { 
        char c = str.charAt(i); 
        // Check if the character is valid for UTF-8 
        if (c >= 0 && c <= 127) { 
            // Character is valid, append it to the escaped buffer 
            escaped.append((byte)c); 
        } else { 
            // Character is not valid for UTF-8, append a UTF-8 escape sequence instead 
            escaped.append((byte) '#'); 
            escaped.append((byte) 'u'); 
            escaped.append((byte) '0'); 
            escaped.append((byte) '0' + (c >>> 12 & 0xF)); 
            escaped.append((byte) '0' + (c >>> 8 & 0xF)); 
            escaped.append((byte) '0' + (c >>> 4 & 0xF)); 
            escaped.append((byte) '0' + (c & 0xF)); 
        } 
    } 
    return escaped; 
}

