            builder.append(" [").append(event.getNDC().getData()).append("]");
        }

        // Append any MD5 information
        if (event.getMDC() != null && event.getMDC().getData() != null) {
            builder.append(" [").append(event.getMDC().getData()).append("]");
        }

        return builder.toString();
    }
