* @param constantPoolEntryIndex the index of a CONSTANT_Utf8 entry in the class's constant pool table
* @param charBuffer the buffer to be used to read the string
* @return the String corresponding to the specified CONSTANT_Utf8 entry
*/
final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // A UTF-8 encoded string in the constant pool takes up 3 or 4 bytes in the constant_pool_entry:
    // type (1 byte), decompressed length (2 bytes or 4 bytes) and then compressed data 
    // of length "decompressed length"
    byte[] constantPoolEntry = new byte[4];
    // Get the next 3 or 4 bytes in the constant_pool_entry array starting at offset
    // constantPoolEntryIndex * 4
    int bytesRead = classFileBuffer.read(constantPoolEntry, 0, 4);
    // Check if the given index is in range
    if (constantPoolEntryIndex * 4 > classFileBuffer.limit()) {
        throw new IndexOutOfBoundsException("Invalid constant pool entry index " + constantPoolEntryIndex);
    }
    // Get the type of the constant pool entry
    int entryType = constantPoolEntry[0] & 0xFF;
    // Check if the entry type is CONSTANT_Utf8
    if (entryType != CONSTANT_Utf8) {
        throw new IllegalArgumentException("Unexpected constant pool entry type " + entryType + ". Expected CONSTANT_Utf8.");
    }
    // Get the decompressed length
    int decompressedLength = constantPoolEntry[1] & 0xFF;
    decompressedLength = (decompressedLength << 8) | (constantPoolEntry[2] & 0xFF);
    if (constantPoolEntry[3] < 0 || characterBuffer < 0) {
        throw new IllegalArgumentException("Illegal decompressed length " + decompressedLength);
    }
    // Get the compressed data
    byte[] compressedData = new byte[3];
    // Copy the 3 or 4 bytes of the constant pool entry to the compressed data array starting at offset 1
    System.arraycopy(constantPoolEntry, 1, compressedData, 0, constantPoolEntry[3]);
    // Decode the UTF-8 string
    return decodeUtf8(decompressedLength, compressedData, charBuffer);
}

/**
* Decodes a UTF-8 string.
* @param decompressedLength the length of the decompressed string
* @param compressedData the compressed data
* @param charBuffer the buffer to be used to store the  decoded string
* @return the decoded UTF-8 string
*/
private static String decodeUtf8(final int decompressedLength, final byte[] compressedData, final char[] charBuffer) {
    // Determine the number of bytes to be uncompressed
    int numBytesToUncompress = compressedData[0] & 0xFF;
    // Check if the number of bytes to be uncompressed is within the bounds of the compressed data
    if (numBytesToUncompress > decompressedLength || numBytesToUncompress > compressedData.length) {
        throw new IllegalArgumentException("Invalid compressed data with length " + numBytesToUncompress + ". Cannot uncompress more than " + decompressedLength + " bytes.");
    }
    // Decode the UTF-8 bytes
    int numChars = 0;
    int byteIndex = 1;
    int charOffset = 0;
    while (byteIndex < numBytesToUncompress) {
        // Decode the next byte
        char c = (char) compressedData[byteIndex++];
        // Determine the number of bytes to read for this character
        int bytesToRead;
        if (c <= 0x7F) {
            bytesToRead = 1;
        } else if (c <= 0xDF) {
            bytesToRead = 2;
        } else {
            bytesToRead = 3;
        }
        // Check if the buffer has enough space to store the decoded bytes
        if (bytesToRead > charBuffer.length - charOffset) {
            throw new ArrayIndexOutOfBoundsException("Insufficient space in the buffer to store the decoded string of length " + numBytesToUncompress);
        }
        // Read the remaining bytes
        for (int i = 1; i < bytesToRead; i++) {
            // Check if there is another byte to read
            if (byteIndex >= numBytesToUncompress) {
                throw new IndexOutOfBoundsException("Unexpected end of compressed data when reading byte " + i + " of character " + numChars);
            }
            // Read the next byte and shift the previous bits
            c |= ((char) compressedData[byteIndex++]) << ((i - 1) * 6);
        }
        // Store the decoded character
        charBuffer[charOffset++] = c;
        numChars++;
    }
    // Truncate the buffer if necessary
    if (charBuffer.length != numChars) {
        charBuffer = Arrays.copyOf(charBuffer, numChars);
    }
    // Convert the buffer to a string
    return new String(charBuffer);
}

