public class ByteArrayDataSource {
  private byte[] data;
  private int pos;

  public ByteArrayDataSource(byte[] data) {
    this.data = data;
    this.pos = 0;
  }

  public byte[] readBytes(int bufferSize) throws IOException {
    if (pos >= data.length) {
      throw new IOException("No more data available");
    }
    int remaining = data.length - pos;
    int size = Math.min(remaining, bufferSize);
    byte[] buffer = new byte[size];
    System.arraycopy(data, pos, buffer, 0, size);
    pos += size;
    return buffer;
  }

  public byte[] readAdditionalBytes(byte[] buffer, int bufferSize) throws IOException {
    int size = 0;
    while (size < bufferSize && pos < data.length) {
      buffer[size++] = data[pos++];
    }
    if (size < bufferSize) {
      throw new IOException("No more data available");
    }
    return buffer;
  }
}

