 * Converts a byte array to an array of {@code int}.
 *
 * @param bytes the byte array to convert
 * @return the array of {@code int}
 * @throws IllegalArgumentException if the {@code bytes} parameter is null or has a length that is not a multiple of 4
 */
public static int[] toIntArray(byte[] bytes){
    if(bytes == null || bytes.length % 4 != 0){
        throw new IllegalArgumentException("Parameter bytes cannot be null or have a length that is not a multiple of 4");
    }

    int[] ints = new int[bytes.length / 4];
    for (int i = 0; i < bytes.length; i += 4) {
        ints[i / 4] = (((bytes[i] & 0xff) << 24) | ((bytes[i + 1] & 0xff) << 16)) | ((bytes[i + 2] & 0xff) << 8) | ((bytes[i + 3] & 0xff) << 0);
    }

    return ints;
}

