public static byte[] toByteArray2(int[] ints){
    if(ints == null || ints.length == 0){
        throw new IllegalArgumentException("Parameter ints cannot be null or empty");
    }

    byte[] bytes = new byte[ints.length * 4];
    for (int i = 0; i < ints.length; i++) {
        bytes[i * 4] = (byte) ((ints[i] >> 24) & 0xff);
        bytes[(i * 4) + 1] = (byte) ((ints[i] >> 16) & 0xff);
        bytes[(i * 4) + 2] = (byte) ((ints[i] >> 8) & 0xff);
        bytes[(i * 4) + 3] = (byte) ((ints[i] >> 0) & 0xff);
    }

    return bytes;
}

