// Helper method to get all edges between a set of vertices in a graph
private static <V, E> Set<E> getAllEdges(Graph<V, E> graph, Set<V> vertices) {
    Set<E> edges = new HashSet<>();
    for (V vertex : vertices) {
        for (E edge : graph.edgesOf(vertex)) {
            // Check if the edge is between two vertices in the given set
            V otherVertex = graph.getEdgeSource(edge);
            if (vertices.contains(otherVertex)) {
                edges.add(edge);
            }
        }
    }
    return edges;
}

