public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (isDataLine(line)) {
                ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
                threadSnapshots.add(threadSnapshot);
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from file", e);
    }
    // Filter out thread snapshots outside of the specified time range
    for (Iterator<ThreadSnapshot> it = threadSnapshots.iterator(); it.hasNext();) {
        ThreadSnapshot threadSnapshot = it.next();
        if (isOutsideTimeRange(threadSnapshot, timeRanges)) {
            it.remove();
        }
    }
    return threadSnapshots;
}

private static boolean isDataLine(String line) {
    return !line.startsWith("#") && line.length() > 0;
}

private static ThreadSnapshot parseThreadSnapshot(String line) {
    String[] columns = line.split(",");
    long timestamp = Long.parseLong(columns[0]);
    int threadId = Integer.parseInt(columns[1]);
    long threadNameOffset = Long.parseLong(columns[2]);
    long nativeMethodOffset = Long.parseLong(columns[3]);
    int operandStackOffset = Integer.parseInt(columns[4]);
    int localVariableOffset = Integer.parseInt(columns[5]);
    return new ThreadSnapshot(timestamp, threadId, threadNameOffset, nativeMethodOffset, operandStackOffset, localVariableOffset);
}

private static boolean isOutsideTimeRange(ThreadSnapshot threadSnapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if ((threadSnapshot.getTimestamp() >= timeRange.getStartTime() && threadSnapshot.getTimestamp() < timeRange.getEndTime())) {
            return false;
        }
    }
    return true;
}
